#!/usr/bin/env node
/**
 * Vendors monaco-vim into vendor/monaco-vim.js.
 *
 * Why patch the upstream bundle at all?
 *
 * leetgpu.com loads monaco-editor 0.52.x from jsDelivr through the AMD loader
 * (`vs/editor/editor.main`). That loader leaves `define.amd` on the page, so the
 * upstream UMD build of monaco-vim takes its AMD branch
 * (`define(['exports', 'monaco-editor/esm/vs/editor/editor.api'], factory)`)
 * and never publishes a global. It also captures `window.monaco` at load time,
 * which forbids loading the file before monaco is ready.
 *
 * The patch replaces the UMD wrapper with a plain IIFE that
 *   1. skips the CommonJS/AMD branches, and
 *   2. exposes `window.MonacoVim` while resolving the monaco API lazily through
 *      a Proxy, so the file may be injected at document_start.
 * The module body itself is untouched.
 *
 * Usage:
 *   node tools/vendor.mjs           # download, verify sha512, patch, write vendor/
 *   node tools/vendor.mjs --check   # same download + verification, but assert that
 *                                   # the files on disk already match (used by CI)
 */
import { createHash } from "node:crypto";
import { readFileSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { gunzipSync } from "node:zlib";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

const UPSTREAM = {
  name: "monaco-vim",
  version: "0.4.4",
  tarball: "https://registry.npmjs.org/monaco-vim/-/monaco-vim-0.4.4.tgz",
  // sha512 (base64) from the npm registry metadata / tarball integrity field.
  integrity:
    "sha512-LNChAb//WEm/W+eyeHG/0+pdVEHotk2hLTN+M3sQZx5E8cAlSWSgqcxpcRuQnxDybSln7pfHF9i63HmbIQvrWw==",
  entry: "package/dist/monaco-vim.umd.js",
  license: "package/LICENSE",
};

const ORIGINAL_HEADER = `(function(global, factory) {
  typeof exports === 'object' && typeof module !== 'undefined' ?  factory(exports, require('monaco-editor/esm/vs/editor/editor.api')) :
  typeof define === 'function' && define.amd ? define(['exports', 'monaco-editor/esm/vs/editor/editor.api'], factory) :
  (global = typeof globalThis !== 'undefined' ? globalThis : global || self, factory((global.MonacoVim = {}), global.monaco));
})(this, function(exports, monaco_editor_esm_vs_editor_editor_api) {`;

const PATCHED_HEADER = `(function(global, factory) {
  // Patched by tools/vendor.mjs, see that file for the reasoning.
  global = typeof globalThis !== "undefined" ? globalThis : global || self;
  var resolveMonacoApi = function() {
    var api = global.monaco;
    if (!api) throw new Error("monaco-vim: window.monaco is not available yet");
    return api;
  };
  var monacoApiProxy = new Proxy({}, {
    get: function(_target, key) { return resolveMonacoApi()[key]; },
    has: function(_target, key) { return key in resolveMonacoApi(); }
  });
  factory((global.MonacoVim = {}), monacoApiProxy);
})(this, function(exports, monaco_editor_esm_vs_editor_editor_api) {`;

const BANNER = `/*!
 * monaco-vim v${UPSTREAM.version} — MIT License — https://github.com/brijeshb42/monaco-vim
 * Generated by tools/vendor.mjs; do not edit by hand.
 * See vendor/monaco-vim.LICENSE for the upstream license text.
 */`;

function fail(message) {
  console.error(`vendor: ${message}`);
  process.exit(1);
}

function extractTarEntry(tar, wanted) {
  let offset = 0;
  while (offset + 512 <= tar.length) {
    const header = tar.subarray(offset, offset + 512);
    if (header.every((byte) => byte === 0)) break;
    const field = (start, end) =>
      header.subarray(start, end).toString("utf8").replace(/\0.*$/s, "").trim();
    const name = field(0, 100);
    const prefix = field(345, 500);
    const fullName = prefix ? `${prefix}/${name}` : name;
    const size = parseInt(field(124, 136), 8) || 0;
    const bodyStart = offset + 512;
    if (fullName === wanted) return tar.subarray(bodyStart, bodyStart + size);
    offset = bodyStart + Math.ceil(size / 512) * 512;
  }
  return fail(`tarball entry not found: ${wanted}`);
}

const response = await fetch(UPSTREAM.tarball);
if (!response.ok) fail(`download failed: HTTP ${response.status}`);
const tarball = Buffer.from(await response.arrayBuffer());

const digest = createHash("sha512").update(tarball).digest("base64");
if (`sha512-${digest}` !== UPSTREAM.integrity) {
  fail(`integrity mismatch for ${UPSTREAM.tarball}\n  expected ${UPSTREAM.integrity}\n  actual   sha512-${digest}`);
}

const tar = gunzipSync(tarball);
const source = extractTarEntry(tar, UPSTREAM.entry).toString("utf8").replace(
  /\n\/\/# sourceMappingURL=.*\n?$/,
  "\n",
);

if (!source.startsWith(ORIGINAL_HEADER)) {
  fail(
    "the UMD header of the upstream bundle changed; tools/vendor.mjs needs to be updated:\n" +
      source.slice(0, ORIGINAL_HEADER.length + 40),
  );
}

const patched = `${BANNER}\n${source.replace(ORIGINAL_HEADER, PATCHED_HEADER)}`;
const license = extractTarEntry(tar, UPSTREAM.license).toString("utf8");

if (process.argv.includes("--check")) {
  const drifted = [
    ["vendor/monaco-vim.js", patched],
    ["vendor/monaco-vim.LICENSE", license],
  ].filter(([file, expected]) => readFileSync(join(ROOT, file), "utf8") !== expected);

  if (drifted.length > 0) {
    fail(
      `${drifted.map(([file]) => file).join(", ")} does not match ${UPSTREAM.name}@${UPSTREAM.version} — run: node tools/vendor.mjs`,
    );
  }
  console.log(`vendor: vendor/ matches ${UPSTREAM.name}@${UPSTREAM.version} (sha512 + patch verified)`);
} else {
  mkdirSync(join(ROOT, "vendor"), { recursive: true });
  writeFileSync(join(ROOT, "vendor/monaco-vim.js"), patched);
  writeFileSync(join(ROOT, "vendor/monaco-vim.LICENSE"), license);

  console.log(
    `vendor: wrote vendor/monaco-vim.js (${patched.length} bytes) from ${UPSTREAM.name}@${UPSTREAM.version}`,
  );
  console.log("vendor: wrote vendor/monaco-vim.LICENSE");
}
